//! Split publication admits prefix/tail/identity/parent backing as one bundle.
use super::*;
#[test]
fn text_split_joint_storage_refusal_actual_ledger_and_no_slot_stable_identities(){
 for mode in 0..3{let mut doc=crate::html::parse("<html><body><span id=parent>😀</span></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);if mode==0{assert_eq!(page.console_eval(&mut doc,&mut forms,"var parent=document.getElementById('parent'),text=parent.firstChild,range=document.createRange();range.setStart(text,0);range.setEnd(text,2);").errors,0);}else{if mode==2{page.state.node_limit=doc.nodes.len();}assert_eq!(page.console_eval(&mut doc,&mut forms,"var owner=new Document(),parent=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),text=owner.createTextNode('😀');parent.appendChild(text);").errors,0);}let Value::Host(source)=page.runtime.execute("text",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};let Value::Host(parent)=page.runtime.execute("parent",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("parent")};page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};assert!(matches!(b.native_whole_text(source).unwrap(),Value::String(s) if s=="😀"));let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.doc.nodes.len(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits);let copies=b.state.copy_work;let limit=b.state.retained_limit;b.state.copy_work=0;assert!(b.prepare_native_text_split(source,&[Value::Number(1.0)]).is_err());assert!(b.state.text_split_plan.is_none());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.doc.nodes.len(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits),before);b.state.copy_work=copies;let info=b.prepare_native_text_split(source,&[Value::Number(1.0)]).unwrap();assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.doc.nodes.len(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits),before);b.state.retained_limit=before.0;assert!(b.commit_native_text_split(source).is_err());assert!(b.state.text_split_plan.is_none());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.doc.nodes.len(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits),before);assert_eq!(b.character_data_source(source).unwrap().code_units().collect::<Vec<_>>(),vec![0xd83d,0xde00]);if mode==0{assert_eq!(b.state.ranges[0].end.offset,2);}b.state.retained_limit=limit;b.state.copy_work=copies;let next=b.prepare_native_text_split(source,&[Value::Number(1.0)]).unwrap();assert_eq!(next.node,info.node);let plan=b.state.text_split_plan.as_ref().unwrap();let(payload,released,metadata)=(plan.payload,plan.released,plan.metadata);let registry_before=b.state.inert_documents.entries.capacity()*size_of::<Entry>()+b.state.inert_documents.generated.capacity()*size_of::<GeneratedNode>();let tail=b.commit_native_text_split(source).unwrap();assert_eq!(tail,next.node);assert_eq!(b.character_data_source(source).unwrap().code_units().collect::<Vec<_>>(),vec![0xd83d]);assert_eq!(b.character_data_source(tail).unwrap().code_units().collect::<Vec<_>>(),vec![0xde00]);let registry_after=b.state.inert_documents.entries.capacity()*size_of::<Entry>()+b.state.inert_documents.generated.capacity()*size_of::<GeneratedNode>();assert_eq!(b.state.retained,before.0-released+payload+metadata+registry_after-registry_before);/* Read-time tree rebuild can independently compact and refund state backing. */assert!(matches!(b.native_whole_text(source).unwrap(),Value::String(s) if s=="😀"));if mode==0{assert_eq!(b.doc.nodes[node_index(parent).unwrap()].children,[node_index(source).unwrap(),node_index(tail).unwrap()]);assert_eq!(b.state.ranges[0].start.node,source);assert_eq!(b.state.ranges[0].end.node,tail);assert_eq!(b.state.ranges[0].end.offset,1);}else{assert_eq!(b.inert_children(parent).unwrap(),[source,tail]);assert_eq!(b.doc.nodes.len(),before.2+usize::from(mode==1));assert_eq!(node_index(tail).is_none(),mode==2);}}
}
